                # Need at least one match before continuing to next part
                return (first_match and backtrack(p_index, t_index + 1) or
                        (first_match and backtrack(p_index + 2, t_index)))

        if first_match:
            return backtrack(p_index + 1, t_index + 1)

        return False

    return backtrack(0, 0)
